import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { ButtonModule } from 'primeng/button';
import { InputTextModule } from 'primeng/inputtext';
import { ToastModule } from 'primeng/toast';
import { MessageService } from 'primeng/api';
import { ProgressSpinnerModule } from 'primeng/progressspinner';
import { ThemeSwitcherComponent } from '../../../shared/features/home/components/theme-switcher/theme-switcher.component';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-forgot-password',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ButtonModule,
    InputTextModule,
    ToastModule,
    ProgressSpinnerModule,
    ThemeSwitcherComponent
  ],
  template: `
    <div class="forgot-container" [class]="currentTheme + '-theme'">
      <p-toast position="top-right"></p-toast>

      <div class="forgot-wrapper">
        <div class="forgot-card">
          <app-theme-switcher></app-theme-switcher>

          <div class="forgot-header">
            <div class="logo-icon"><i class="pi pi-lock"></i></div>
            <h2>¿Olvidaste tu contraseña?</h2>
            <p>Verifica tu identidad para restablecer tu contraseña</p>
          </div>

          <form (ngSubmit)="onSubmit()" *ngIf="!loading">
            <div class="form-group">
              <label for="email">Correo Electrónico</label>
              <div class="input-wrapper">
                <i class="pi pi-envelope input-icon"></i>
                <input
                  pInputText
                  type="email"
                  id="email"
                  [(ngModel)]="email"
                  name="email"
                  placeholder="tu@email.com"
                  required
                  autofocus>
              </div>
            </div>

            <button type="submit" class="btn-submit" [disabled]="!email || loading">
              <i class="pi pi-send"></i>
              {{ loading ? 'Verificando...' : 'Verificar identidad' }}
            </button>

            <div class="back-link">
              <a (click)="goToLogin()"><i class="pi pi-arrow-left"></i> Volver al login</a>
            </div>
          </form>

          <div *ngIf="errorMessage" class="error-message">
            <i class="pi pi-exclamation-triangle"></i>
            <p>{{ errorMessage }}</p>
            <button class="btn-secondary" (click)="errorMessage = ''">Reintentar</button>
          </div>
        </div>
      </div>
    </div>
  `,
  styleUrls: ['./forgot-password.component.less']
})
export class ForgotPasswordComponent implements OnInit {
  email = '';
  loading = false;
  errorMessage = '';
  currentTheme = 'light';

  constructor(
    private router: Router,
    private authService: AuthService,
    private messageService: MessageService
  ) {}

  ngOnInit(): void {
    this.loadTheme();
  }

 onSubmit(): void {
  if (!this.email) return;

  this.loading = true;
  this.errorMessage = '';

  this.authService.solicitarResetPassword({ email: this.email }).subscribe({
    next: (response) => {
      this.loading = false;

      // ✅ Redirigir directamente, no mostrar mensaje de correo
      this.router.navigate(['/reset-password'], {
        state: {
          resetToken: response.token,
          email: this.email
        }
      });
    },
    error: (error) => {
      this.loading = false;
      // ✅ Mensaje genérico pero honesto
      this.errorMessage = 'Error al verificar el correo. Por favor, intente nuevamente.';
      console.error('Error:', error);
    }
  });
}

  goToLogin(): void {
    this.router.navigate(['/login']);
  }

  private loadTheme(): void {
    this.currentTheme = localStorage.getItem('theme') as 'light' | 'dark' || 'light';
    document.body.classList.add(`${this.currentTheme}-theme`);
  }
}
